/**
 * Password Template Script
 * ------------------------------------------------------------------------------
 * A file that contains scripts highly couple code to the Password template.
 *
 * @namespace password
 */
import { getElement, getElements } from '../../utils/functional';
const selectors = {
  recoverPasswordFormTriggers: '[data-recover-toggle]',
  recoverPasswordForm: '[data-recover-form]',
  loginForm: '[data-login-form]',
  formState: '[data-form-state]',
  resetSuccess: '[data-reset-success]'
};
const classes = {
  hide: 'util-Hide'
};

function onShowHidePasswordForm(evt) {
  evt.preventDefault();
  toggleRecoverPasswordForm();
}

function checkUrlHash() {
  const hash = window.location.hash; // Allow deep linking to recover password form

  if (hash === '#recover') {
    toggleRecoverPasswordForm();
  }
}
/**
 *  Show/Hide recover password form
 */


function toggleRecoverPasswordForm() {
  getElement(selectors.recoverPasswordForm).classList.toggle(classes.hide);
  getElement(selectors.loginForm).classList.toggle(classes.hide);
}
/**
 *  Show reset password success message
 */


function resetPasswordSuccess() {
  // check if reset password form was
  // successfully submitted and show success message.
  if (getElement(selectors.formState)) {
    getElement(selectors.resetSuccess).classList.remove(classes.hide);
  }
}

if (getElement(selectors.recoverPasswordForm)) {
  checkUrlHash();
  resetPasswordSuccess();
  getElements(selectors.recoverPasswordFormTriggers).forEach(trigger => {
    trigger.addEventListener('click', onShowHidePasswordForm);
  });
}